// Generated by Viscosity: "rs" stored as a struct of arrays (fields x).
class __Vsc_rs {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.x = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_rs(Math.max(16, v.length / 1)); for (let i = 0; i < v.length; i += 1) c.push(v[i + 0]); return c; }
  push(v0) { const n = this.length; if (n === this.cap) this.grow(); this.x[n] = v0; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.x); this.x = t; }
}
// viscosity: qs=aos, rs=soa
const qs = []; // @viscosity aos
const rs = new __Vsc_rs();
for (let i = 0; i < 100; i++) { qs.push({ x: i }); rs.push(i); }
let s = 0;
for (let i = 0; i < qs.length; i++) s += qs[i].x + rs.x[i];
console.log(s);
